const uint8_t *ui_font16_bits(uint32_t cp)
{
    for (int i = 0; i < UI_FONT_N; ++i) {
        if (s_glyphs[i].cp == cp) return s_glyphs[i].bits;
    }
    return NULL;
}

int ui_font16_advance(uint32_t cp)
{
    if (cp < 0x80) return 9;
    return 16;
}
